#include <stdio.h>
#include <stdlib.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int *a = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    int pos; scanf("%d", &pos);
    if (n == 1) puts("(empty)");
    else {
        int first = 1;
        for (int i = 0; i < n; i++) {
            if (i == pos) continue;
            if (!first) putchar(' ');
            printf("%d", a[i]); first = 0;
        }
        putchar('\n');
    }
    free(a);
    return 0;
}

code.C++:
#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n; if (cin >> n) {
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];
        int pos; cin >> pos;
        if (n == 1) cout << "(empty)\n";
        else {
            bool first = true;
            for (int i = 0; i < n; i++) {
                if (i == pos) continue;
                if (!first) cout << " ";
                cout << a[i]; first = false;
            }
            cout << "\n";
        }
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = sc.nextInt();
            int pos = sc.nextInt();
            if (n == 1) System.out.println("(empty)");
            else {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < n; i++) {
                    if (i == pos) continue;
                    if (sb.length() > 0) sb.append(" ");
                    sb.append(a[i]);
                }
                System.out.println(sb.toString());
            }
        }
    }
}

