const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/).map(Number);
    if (toks.length > 0) {
        const n = toks[0];
        const arr = toks.slice(1, 1 + n);
        const pos = toks[1 + n];
        if (pos >= 0 && pos < arr.length) arr.splice(pos, 1);
        console.log(arr.length > 0 ? arr.join(" ") : "(empty)");
    }
}
main();

